using EnigmaLogic.Models;
using EnigmaLogic.Models.ChatGpt;
using EnigmaLogic.Services;

namespace Tests.EvaluationHarness;

/// <summary>
/// Test suite and automated evaluation harness benchmarks for <see cref="EnigmaPredictChatGPTService"/>
/// as generated by ChatGPT without any external handholding, custom tuning, or injected helper models.
/// </summary>
[TestClass]
public class EnigmaPredictChatGPTServiceTests
{
    public TestContext? TestContext { get; set; }

    // =========================================================================
    // 1. SIMULATION & HISTORICAL TEST VECTORS
    // =========================================================================

    [TestMethod]
    public void Simulate_HistoricalEnigmaVector_ProducesBDZGO()
    {
        var service = new EnigmaPredictChatGPTService();
        var settings = new EnigmaSettings('A', 'A', 'A', []);

        EnigmaOutput output = service.Simulate("AAAAA", settings);

        Assert.AreEqual("BDZGO", output.OutputText);
        Assert.AreEqual(('A', 'A', 'F'), output.FinalRotorPositions);
    }

    [TestMethod]
    public void Simulate_MiddleRotorOnNotch_DoubleStepsCorrectly()
    {
        var service = new EnigmaPredictChatGPTService();
        var settings = new EnigmaSettings('A', 'D', 'U', []);

        EnigmaOutput output = service.Simulate("AAAA", settings);

        Assert.AreEqual(('B', 'F', 'Y'), output.FinalRotorPositions);
    }

    [TestMethod]
    public void Simulate_WithPlugboardAndArbitraryPositions_MatchesEnigmaSimService()
    {
        var settings = new EnigmaSettings('M', 'E', 'K', ["AN", "EZ", "HK", "IJ", "LR", "MQ", "OT", "PV", "SW", "UX"]);
        const string message =
            "OPERATIONOVERLORDWEATHERFORECASTFORTHEENGLISHCHANNELISCLEARANDFAVORABLEFORALLIEDLANDINGSATNORMANDY";

        var simService = new EnigmaSimService();
        simService.Configure(settings, RandomSettings: false);
        string expectedCiphertext = simService.Process(message);

        var chatGptService = new EnigmaPredictChatGPTService();
        EnigmaOutput actualOutput = chatGptService.Simulate(message, settings);

        Assert.AreEqual(expectedCiphertext, actualOutput.OutputText);
        Assert.AreEqual(simService.LastOutput!.FinalRotorPositions, actualOutput.FinalRotorPositions);

        EnigmaOutput decrypted = chatGptService.Simulate(actualOutput.OutputText, settings);
        Assert.AreEqual(message, decrypted.OutputText);
    }

    // =========================================================================
    // 2. STATISTICAL ANALYSIS (IC, CHI-SQUARED)
    // =========================================================================

    [TestMethod]
    public void AnalyzeText_EnglishPlaintextVsRandomCiphertext_DistinguishesICAndChiSquared()
    {
        var service = new EnigmaPredictChatGPTService();

        const string englishPlaintext =
            "OPERATIONOVERLORDWEATHERFORECASTFORTHEENGLISHCHANNELISCLEARANDFAVORABLEFORALLIEDLANDINGSATNORMANDY";

        EnigmaOutput encrypted = service.Simulate(
            englishPlaintext,
            new EnigmaSettings('Q', 'E', 'V', ["AB", "CD", "EF", "GH", "IJ"]));

        EnigmaTextAnalysis plainAnalysis = service.AnalyzeText(englishPlaintext);
        EnigmaTextAnalysis cipherAnalysis = service.AnalyzeText(encrypted.OutputText);

        Assert.IsGreaterThan(cipherAnalysis.IndexOfCoincidence, plainAnalysis.IndexOfCoincidence);
        Assert.IsLessThan(cipherAnalysis.ChiSquared, plainAnalysis.ChiSquared);
    }

    // =========================================================================
    // 3. CRYPTANALYSIS & EDGE-CASE VALIDATION (AS GENERATED)
    // =========================================================================

    [TestMethod]
    public async Task CrackAsync_InvalidAndEdgeCaseInputs_ThrowsDocumentedValidationExceptions()
    {
        var service = new EnigmaPredictChatGPTService();

        await Assert.ThrowsExactlyAsync<ArgumentNullException>(() => service.CrackAsync(null!));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync(""));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("12345!@#$%"));
        await Assert.ThrowsExactlyAsync<ArgumentException>(() => service.CrackAsync("SHORTTEXT"));
    }

    [TestMethod]
    public async Task CrackAsync_DefaultConstructorWithoutInjectedModel_ThrowsInvalidOperationException()
    {
        // Because ChatGPT generated EnigmaPredictChatGPTService(EnigmaNGramModel? defaultModel = null)
        // without a built-in default n-gram table, calling CrackAsync out-of-the-box throws InvalidOperationException.
        var service = new EnigmaPredictChatGPTService();
        const string sampleCipher = "BDZGOWETTERBERICHTKLAROPERATIONOVERLORD";

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            () => service.CrackAsync(sampleCipher));
    }

    // =========================================================================
    // 4. EVALUATION HARNESS SUITE FOR CHATGPT SERVICE (UNMODIFIED)
    // =========================================================================

    [TestMethod]
    public async Task EvaluationHarness_ChatGptServiceAsGenerated_RecordsBaselineMetrics()
    {
        // Instantiate ChatGPT's service with its default parameterless constructor and default options
        var chatGptService = new EnigmaPredictChatGPTService();
        var candidate = new ChatGptCrackCandidate(chatGptService, options: null, "ChatGPT-AsGenerated");

        IReadOnlyList<GroundTruthCase> groundTruthCases = GroundTruthDatasetGenerator.CreateStandardBenchmarkSuite();
        var runner = new EnigmaBenchmarkRunner(groundTruthCases);

        string chatGptSourcePath = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "EnigmaLogic", "Services", "EnigmaPredictChatGPTService.cs"));

        Assert.IsTrue(File.Exists(chatGptSourcePath), $"Expected source file at {chatGptSourcePath}");

        ModelEvaluationReport report = await runner.EvaluateCandidateAsync(candidate, chatGptSourcePath);

        Assert.AreEqual("ChatGPT-AsGenerated", report.ModelName);
        Assert.AreEqual(groundTruthCases.Count, report.TotalRuns);
        Assert.AreEqual(0.0, report.DecryptionSuccessRate, 1e-9);
        Assert.AreEqual(1.0, report.AverageCharacterErrorRate, 1e-9);
        Assert.AreEqual(0.0, report.AverageStateReconstructionAccuracy, 1e-9);
        Assert.AreEqual(1.0, report.EdgeCasePassRate, 1e-9);
        Assert.IsGreaterThan(1.0, report.AverageCyclomaticComplexity);

        TestContext?.WriteLine("=== ChatGPT Evaluation Harness Report (As Generated / No Handholding) ===");
        TestContext?.WriteLine($"Model:                        {report.ModelName}");
        TestContext?.WriteLine($"Total Runs:                   {report.TotalRuns}");
        TestContext?.WriteLine($"Decryption Success Rate (DSR): {report.DecryptionSuccessRate:P1}");
        TestContext?.WriteLine($"Average CER:                  {report.AverageCharacterErrorRate:P2}");
        TestContext?.WriteLine($"State Reconstruction Acc:     {report.AverageStateReconstructionAccuracy:P1}");
        TestContext?.WriteLine($"Avg Execution Time:           {report.AverageExecutionTime.TotalMilliseconds:F2} ms");
        TestContext?.WriteLine($"Edge-Case Pass Rate:          {report.EdgeCasePassRate:P0}");
        TestContext?.WriteLine($"Avg Cyclomatic Complexity:    {report.AverageCyclomaticComplexity:F2} (Max: {report.MaxCyclomaticComplexity})");
        foreach (SingleRunMetrics run in report.RunDetails)
        {
            TestContext?.WriteLine($"  [{run.CaseId}] Match={run.IsExactMatch}, CER={run.CharacterErrorRate:P0}, Error={run.ErrorMessage ?? "None"}");
        }
    }

    [TestMethod]
    public void CyclomaticComplexity_ChatGptService_ProducesDetailedMethodBreakdown()
    {
        string chatGptSourcePath = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "..", "EnigmaLogic", "Services", "EnigmaPredictChatGPTService.cs"));

        FileComplexityReport complexityReport = CyclomaticComplexityAnalyzer.AnalyzeFile(chatGptSourcePath);

        Assert.IsGreaterThan(10, complexityReport.MethodCount);
        Assert.IsGreaterThan(1.0, complexityReport.AverageCyclomaticComplexity);

        TestContext?.WriteLine(
            $"EnigmaPredictChatGPTService.cs: {complexityReport.MethodCount} methods, " +
            $"Avg CC = {complexityReport.AverageCyclomaticComplexity:F2}, " +
            $"Max CC = {complexityReport.MaxCyclomaticComplexity}, " +
            $"Exceeding McCabe (>10) = {complexityReport.MethodsExceedingThreshold}");

        foreach (MethodComplexityMetric method in complexityReport.Methods)
        {
            TestContext?.WriteLine(
                $"  - {method.MethodSignature}: CC = {method.CyclomaticComplexity}" +
                (method.ExceedsMcCabeThreshold ? " [>10]" : ""));
        }
    }
}
